```c++
#include <iostream>
#include <string>
#include <regex>
#include <algorithm>

std::string convertMarkdownToHTML(const std::string& markdown) {
    // Define Markdown syntax and corresponding HTML tags
    std::map<std::string, std::string> markdown_syntax = {
        {"#", "<h1>"},
        {"##", "<h2>"},
        {"###", "<h3>"},
        {"####", "<h4>"},
        {"#####", "<h5>"},
        {"######", "<h6>"},
        {"*", "*"},
        {"_", "_"},
        {"![<MARKDOWN>](<URL>)", "<img src='<URL>' alt='<MARKDOWN>'/>"},
        {"-|-" ,"<hr>"}
    };

    std::string html;
    // Loop through each line in the markdown text
    for (const std::string& line : std::istringstream(markdown).str()) {
        // Check if the line starts with a heading hash sign
        if (std::find_if(line.begin(), line.end(),
            [](char c) { return c == '#'; }) != line.end()) {
            // Replace the heading hash sign with an HTML tag
            line.replace(line.begin(), line.begin() + 1,
                markdown_syntax.find(line.substr(0, 2))->second);
            html += line + "\n";
            continue;
        }

        // Check for italic, bold, or strikethrough formatting
        if (line.find('*') != std::string::npos &&
            line.find('_') == std::string::npos &&
            line.find('~~') == std::string::npos) {
            // Replace "*" with "<em>" and "</em>" for italics
            auto start = line.find('*');
            auto end = line.find_first_of("* ", start + 1);
            html += line.replace(start, (end - start + 1), "<em>") +
                line.replace((end + 1), (end - start + 1), "</em>");

        } else if (line.find('_') != std::string::npos &&
                   line.find('*') == std::string::npos &&
                   line.find('~~') == std::string::npos) {
            // Replace "_" with "<strong>" and "</strong>" for bold
            auto start = line.find('_');
            auto end = line.find_first_of("_ ", start + 1);
            html += line.replace(start, (end - start + 1), "<strong>") +
                line.replace((end + 1), (end - start + 1), "</strong>");

        } else if (line.find('~~') != std::string::npos &&
                   line.find('*') == std::string::npos &&
                   line.find('_') == std::string::npos) {
            // Replace "~~" with "<del>" and "</del>" for strikethrough
            auto start = line.find('~~');
            auto end = line.find_first_of("~~ ", start + 2);
            html += line.replace(start, (end - start + 2),
                "<del>") + line.replace((end + 2), (end - start + 2), "</del>");
        } else if (line.find('![') != std::string::npos &&
                   line.find('](') != std::string::npos) {
            // Replace markdown image syntax with HTML img tag
            auto start = line.find('![');
            auto end = line.find(']');
            auto urlStart = line.find('(', end + 1);
            auto urlEnd = line.find(')', urlStart + 1);
            std::string alt = line.substr(start + 2, end - start - 2);
            std::string url = line.substr(urlStart + 1, urlEnd - urlStart - 1);
            html += line.replace(start, end - start + 1,
                    "<img src='" + url + "' alt='" + alt + "'>");
        } else if (line.find('|-|') != std::string::npos) {
            // Replace the horizontal rule syntax with an HTML <hr> tag
            html += "<hr>";
        } else {
            // No special formatting found, just add the line as is
            html += line + "\n";
        }
    }

    return html;
}
```

