function findPrimeNumber(arr) {
  // Loop through the array
  for (let i = 0; i < arr.length; i++) {
    let num = arr[i];
    // Check if the number is valid (not equal to 1 or 0)
    if (num === 1 || num === 0) continue;
    // Set a flag to indicate prime number found
    let isPrime = true;
    // Check if the number is divisible by any number between 2 and its square root
    for (let j = 2; j <= Math.sqrt(num); j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }
    // If a prime number has been found, print it
    if (isPrime) {
      console.log(`Found a prime number: ${num}`);
      return;
    }
  }
  // If no prime number is found, print a message
  console.log("No prime number found in the given array.");
}

// Example usage:
let numbers = [5, 7, 11, 13, 17];
findPrimeNumber(numbers);
```

